def mapping_from_manifest() -> tuple[dict, dict]:
    if sha256_file(DOWNLOAD_MANIFEST) != EXPECTED_DOWNLOAD_MANIFEST_SHA256:
        raise RuntimeError("H0-F_DOWNLOAD_MANIFEST.json SHA-256已变化，禁止继续点修")
    manifest = json.loads(DOWNLOAD_MANIFEST.read_text(encoding="utf-8"))
    downloads = manifest.get("downloads", [])
    if len(downloads) != 183:
        raise RuntimeError(f"下载manifest条目数不是183：{len(downloads)}")
    mapping: dict[str, str] = {}
    for row in downloads:
        path = row.get("zip_relative_path")
        digest = row.get("local_zip_sha256")
        if path in mapping:
            raise RuntimeError(f"下载manifest存在重复zip_relative_path：{path}")
        if not isinstance(path, str) or not re.fullmatch(r"[0-9a-f]{64}", str(digest or "")):
            raise RuntimeError(f"下载manifest路径或SHA无效：{path}")
        mapping[path] = digest
    return mapping, manifest

