function parseLocal(value) {
  if (!value || value === 107) return null;
  if (value instanceof Date) return value;
  const text = String(value).trim();
  if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(text)) return null;
  const date = new Date(`${text.replace(" ", "T")}+08:00`);
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatLocal(date) {
  if (!date) return "";
  const parts = new Intl.DateTimeFormat("sv-SE", {
    timeZone: "Asia/Hong_Kong",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return `${map.year}-${map.month}-${map.day} ${map.hour}:${map.minute}:${map.second}`;

  const key = condition.condition_role || "其他";
  if (!grouped.has(key)) grouped.set(key, []);
  grouped.get(key).push(condition);
}
for (const [role, rows] of grouped.entries()) {
  rows.sort(
    (a, b) =>
      a.created_at - b.created_at ||
      a.terminal_at - b.terminal_at ||
      a.algorithm_id.localeCompare(b.algorithm_id),
  );
  for (let i = 1; i < rows.length; i += 1) {
    const previous = rows[i - 1];
    const next = rows[i];
    const gap = secondsBetween(previous.terminal_at, next.created_at);
    const sameType = previous.condition_type === next.condition_type;
    const sameDirection = previous.close_direction === next.close_direction;
    const sameBasis = previous.trigger_basis === next.trigger_basis;
    const sameOperator = previous.comparison_operator === next.comparison_operator;
    let level = "相邻记录";
    if ([sameType, sameDirection, sameBasis, sameOperator].some((value) => value === false)) {
      level = "可能无关";
    } else if (gap !== null && gap >= 0 && gap <= 300) {
      level = "疑似连续调整";
    } else if (gap === null) {
      level = "无法判断";
    }
    adjacent.push({
      position_cycle_id: cycleId,
      新T编号: cycleById.get(cycleId)?.新人工复盘编号 || "",
      条件作用类别: role,
      前一algorithm_id: previous.algorithm_id,
      前一状态: previous.status,
      前一terminal_at: previous.terminal_at,
      后一algorithm_id: next.algorithm_id,
      后一created_at: next.created_at,
      时间间隔秒数: gap,
      条件类型是否一致: sameType ? "是" : "否",
      方向是否一致: sameDirection ? "是" : "否",
      触发基准是否一致: sameBasis ? "是" : "否",
      比较符号是否一致: sameOperator ? "是" : "否",
      触发价变化:
        previous.trigger_price !== null && next.trigger_price !== null
          ? next.trigger_price - previous.trigger_price
          : null,
      数量变化:
        previous.quantity !== null && next.quantity !== null
          ? next.quantity - previous.quantity
          : null,
      关系等级: level,
      推断边界: "仅记录相邻和客观变化；未写入“替换/修改/撤单重挂”事实",
    });
  }
}

