function typedMatrix(rawRows) {
  if (rawRows.length === 0) return [["status"], ["EMPTY_SOURCE"]];
  const headers = rawRows[0];
  return rawRows.map((row, rowIndex) =>
    row.map((raw, columnIndex) => {
      if (rowIndex === 0) return raw;
      const header = headers[columnIndex] ?? "";
      if (shouldRemainText(header)) return raw;
      const trimmed = raw.trim();
      if (/^(true|false)$/i.test(trimmed)) return trimmed.toLowerCase() === "true";
      if (/^-?\d+$/.test(trimmed) && trimmed.replace("-", "").length <= 12) return Number(trimmed);
      if (/^-?\d+\.\d+$/.test(trimmed) && trimmed.replace(/[-.]/g, "").length <= 14) return Number(trimmed);
      return raw;
    }),
  );
}

