def patch_interface_iso_text(data: bytes) -> bytes:
    text = data.decode("utf-8")
    pattern = re.compile(r'(<x:c r="D3" s="\d+") t="[^"]*"><x:v>.*?</x:v></x:c>')
    match = pattern.search(text)
    if not match:
        raise RuntimeError("Interface generated_at_utc cell D3 not found")
    replacement = f'{match.group(1)} t="str"><x:v>{ISO_UTC}</x:v></x:c>'
    text = text[:match.start()] + replacement + text[match.end():]
    column_pattern = re.compile(
        r'(<x:col min="4" max="4" width=")[^"]+(" hidden="0" customWidth="1" />)'
    )
    if not column_pattern.search(text):
        raise RuntimeError("Interface value column D definition not found")
    text = column_pattern.sub(r'\g<1>48\2', text, count=1)
    return text.encode("utf-8")

