    visible, deduped, overlaps = sequence_dedupe(image_groups["LIST"])
status_counts = Counter(row["状态"] for row in deduped)
details = [parse_conditional_detail(image) for image in image_groups["CONDITIONAL_DETAIL"]]
base_rows = [parse_base_detail(image) for image in image_groups["BASE_ORDER_DETAIL"]]
if reviewed_screen_index:
    reviewed_details = {
        row["file"]: row
        for row in reviewed_screen_index.get("conditional_details", [])
    }
    for row in details:
        reviewed_row = reviewed_details.get(Path(row["截图来源"]).name)
        if reviewed_row:
            override_fields = [
                ("条件委托列表时间", "condition_list_time"),
                ("合约", "contract"),
                ("类型", "page_type"),
                ("方向", "direction"),
                ("页面价格字段", "page_price"),
                ("数量", "quantity"),
                ("只减仓", "reduce_only"),
                ("只做Maker", "maker_only"),
                ("触发条件", "trigger_condition"),
                ("状态", "status"),
                ("算法ID", "algorithm_id"),
                ("明确触发时间", "trigger_time"),
                ("生成基础订单号", "generated_order_id"),
                ("字段是否清晰", "field_readability"),
            ]
            for target_key, source_key in override_fields:
                value = reviewed_row.get(source_key)
                if value not in (None, ""):
                    row[target_key] = value
            row["关键字段复核"] = "逐图视觉二次核对通过"
    reviewed_bases = {
        row["file"]: row for row in reviewed_screen_index.get("base_orders", [])
    }
    for row in base_rows:
        reviewed_row = reviewed_bases.get(Path(row["截图来源"]).name)
        if reviewed_row:
            row["订单号"] = reviewed_row["order_id"]
            row["基础单类型"] = reviewed_row["page_type"]
            row["视觉复核成交明细"] = reviewed_row["fill_display"]
            row["视觉复核遮挡说明"] = reviewed_row.get("note", "")
            row["关键字段复核"] = "逐图视觉二次核对通过"
base_rows = enrich_base_rows(base_rows, stage_orders, fills)
completed = [row for row in deduped if row["状态"] == "已完成"]
links, completed_checks, missing_expansions = condition_linkages(
    completed, details, base_rows, stage_orders, fills, coverage
)

