const previewDir = "/private/tmp/h0a_workbook_previews";
await Promise.all([fs.mkdir(outputDir, { recursive: true }), fs.mkdir(previewDir, { recursive: true })]);

const analysis = JSON.parse(await fs.readFile(analysisPath, "utf8"));
const headResults = JSON.parse(await fs.readFile(path.join(outputRoot, "日志", "H0-A_HEAD结果.json"), "utf8"));
const sampleGets = JSON.parse(await fs.readFile(path.join(outputRoot, "日志", "H0-A_小样本GET结果.json"), "utf8"));
const baseline = JSON.parse(await fs.readFile(path.join(outputRoot, "日志", "H0-A_旧文件结束比较.json"), "utf8"));
const currentVersion = JSON.parse(
  await fs.readFile(
    path.join(rootPath, "现行正式版_V2.1_136笔主动交易_A497生命周期/00_从这里开始/CURRENT_VERSION.json"),
    "utf8",
  ),
);
const safeSources = JSON.parse(await fs.readFile("/private/tmp/h0a_objective_sources_safe.json", "utf8"));
const headByUrl = new Map(headResults.map((row) => [row.url, row]));

function mapRows(items, columns) {
  return items.map((item) =>
    columns.map((column) => {
      const value = cleanValue(item[column.key]);
      if (
        typeof value === "string" &&
        /^\d{10,}$/.test(value) &&
        /ID|编号/.test(column.label ?? column.key ?? "")
      ) {
        return Number(value);
      }
      return value;
    }),
  );

async function exportVerify(workbook, filename) {
  const sheets = workbook.worksheets.items;
  for (let index = 0; index < sheets.length; index++) {
    const sheet = sheets[index];
    const used = sheet.getUsedRange(true);
    const rowCount = Math.max(1, Math.min(20, used.rowCount ?? 20));
    const colCount = Math.max(1, Math.min(14, used.columnCount ?? 14));
    const range = `A1:${colLetter(colCount)}${rowCount}`;
    const preview = await workbook.render({ sheetName: sheet.name, range, scale: 1, format: "png" });
    const previewName = `${filename.replace(/\.xlsx$/, "")}__${String(index + 1).padStart(2, "0")}_${sheet.name.replace(/[\\/:*?"<>|]/g, "_")}.png`;
    await fs.writeFile(path.join(previewDir, previewName), new Uint8Array(await preview.arrayBuffer()));
  }
  const errors = await workbook.inspect({
    kind: "match",
    searchTerm: "#REF!|#DIV/0!|#VALUE!|#NAME\\?|#N/A",
    options: { useRegex: true, maxResults: 300 },
    summary: `formula error scan ${filename}`,
  });
  if (errors.ndjson.trim() && !errors.ndjson.includes("matched 0 entries")) {
    throw new Error(`formula error in ${filename}: ${errors.ndjson.slice(0, 1000)}`);
  }
  const firstSheet = sheets[0];
  const inspection = await workbook.inspect({
    kind: "table",
    sheetId: firstSheet.name,
    range: `A1:${colLetter(Math.min(10, firstSheet.getUsedRange(true).columnCount ?? 10))}${Math.min(
      20,
      firstSheet.getUsedRange(true).rowCount ?? 20,
    )}`,
    include: "values,formulas",
    tableMaxRows: 20,
    tableMaxCols: 10,
    maxChars: 7000,
  });
  await fs.writeFile(path.join(outputRoot, "日志", `${filename}.inspect.ndjson`), inspection.ndjson);
  const output = await SpreadsheetFile.exportXlsx(workbook);
  await output.save(path.join(outputDir, filename));

const manifest = [];
for (const filename of (await fs.readdir(outputDir)).filter((name) => name.endsWith(".xlsx")).sort()) {
  const bytes = await fs.readFile(path.join(outputDir, filename));
  manifest.push({
    filename,
    bytes: bytes.length,
    sha256: crypto.createHash("sha256").update(bytes).digest("hex"),
  });
}
await fs.writeFile(path.join(outputRoot, "日志", "H0-A_输出工作簿清单.json"), JSON.stringify(manifest, null, 2));
console.log(JSON.stringify({ outputDir, workbooks: manifest }, null, 2));

