const prototypeRel = rel(
  "人工复盘增强版_修正工程",
  "R1_10笔成品原型",
  "30天逐笔人工复盘增强版_10笔成品原型_F2.5.4_WPS实测通过版.xlsx",
);

const technicalMappingPath = path.join(
  dirs.mapping,
  "N1-0_TECHNICAL_SOURCE_MAPPING.csv",
);

const [rootArg, extractedArg] = process.argv.slice(2);
if (!rootArg || !extractedArg) {
  throw new Error("用法: node h0b_prepare_and_head.mjs <H0-B根目录> <H0-A提取JSON>");
}

const root = path.resolve(rootArg);
const extractedPath = path.resolve(extractedArg);
const planDir = path.join(root, "01_下载计划");
const logDir = path.join(root, "日志");
const checkpointDir = path.join(root, "断点");
await Promise.all([fs.mkdir(planDir, { recursive: true }), fs.mkdir(logDir, { recursive: true }), fs.mkdir(checkpointDir, { recursive: true })]);

const REQUIRED_SAMPLES = ["T001", "T029", "T042", "T043", "T049", "T069", "T087", "T120", "T123", "T125"];
const ALLOWED_TYPES = new Set(["markPriceKlines", "klines", "aggTrades"]);
const ALLOWED_HOSTS = new Set(["data.binance.vision", "fapi.binance.com"]);
const extracted = JSON.parse(await fs.readFile(extractedPath, "utf8"));

const h0a02 = workbook("H0-A_02_10笔固定样本客观链核对.xlsx");
const h0a03 = workbook("H0-A_03_10笔持仓阶段需求清单.xlsx");
const h0a05 = workbook("H0-A_05_历史行情档案可得性审计.xlsx");
const h0a06 = workbook("H0-A_06_人工字段隔离检查.xlsx");

const sampleRows = table(sheet(h0a02, "10笔摘要"));
const fillRows = table(sheet(h0a02, "原始Fill链"));
const phaseRows = table(sheet(h0a03, "持仓阶段"));
const demandRows = table(sheet(h0a03, "行情需求去重"));
const auditRows = table(sheet(h0a05, "完整HEAD审计"));
const isolationRows = table(sheet(h0a06, "隔离断言"));

const plan = demandRows.map((row, index) => {
  const symbol = String(row.symbol);
  const utcDate = String(row["UTC日期"]);
  const dataType = String(row["数据类型"]);
  const filename = String(row["预计档案文件名"]);
  const url = String(row["完整档案URL"]);
  if (!ALLOWED_TYPES.has(dataType)) throw new Error(`禁止的数据类型: ${dataType}`);
  if (url.includes("/monthly/") || !url.includes("/daily/")) throw new Error(`非日包URL: ${url}`);
  if (url.includes("/trades/")) throw new Error(`禁止下载trades: ${url}`);
  const parsed = new URL(url);
  if (!ALLOWED_HOSTS.has(parsed.hostname) || parsed.protocol !== "https:") {
    throw new Error(`非允许域名或协议: ${url}`);
  }
  if (!url.includes(`/${symbol}/`) || !filename.includes(symbol) || !filename.includes(utcDate)) {
    throw new Error(`symbol/date/文件名不一致: ${url}`);
  }
  const audit = auditMap.get(`${symbol}|${utcDate}|${dataType}`);
  if (!audit) throw new Error(`H0-A_05找不到逐项审计: ${symbol}/${utcDate}/${dataType}`);
  if (
    String(audit["预计档案文件名"]) !== filename ||
    String(audit["完整档案URL"]) !== url ||
    Number(audit["HEAD状态"]) !== 200
  ) {
    throw new Error(`H0-A_03与H0-A_05不一致: ${symbol}/${utcDate}/${dataType}`);
  }
  return {
    plan_id: `H0B-${String(index + 1).padStart(2, "0")}`,
    symbol,
    contract_type: String(row["合约类型"]),
    position_cycle_ids: String(row["position_cycle_id集合"]),
    new_t_ids: String(row["新T编号集合"]),
    beijing_range: String(row["北京时间范围"]),
    utc_range: String(row["UTC时间范围"]),
    utc_date: utcDate,
    data_type: dataType,
    interval: String(row["周期"]),
    filename,
    url,
    checksum_url: `${url}.CHECKSUM`,
    h0a_head_status: Number(row["HEAD状态"]),
    h0a_content_length: Number(row["Content-Length"]),
    h0a_last_modified: String(row["Last-Modified"]),
    related_phase_count: Number(row["关联阶段数"]),
    source_workbook_demand: h0a03.path,
    source_workbook_audit: h0a05.path,
  };

const contentLengthDifferences = plan
  .map((item) => {
    const head = headResults.find((row) => row.plan_id === item.plan_id);
    return {
      plan_id: item.plan_id,
      h0a_content_length: item.h0a_content_length,
      h0b_content_length: head?.content_length ?? null,
      difference: head?.content_length === item.h0a_content_length ? 0 : (head?.content_length ?? 0) - item.h0a_content_length,
    };
  })
  .filter((row) => row.difference !== 0);

const headResults = [];
for (const item of plan) {
  const result = await headWithRetry(item);
  headResults.push(result);
  await fs.writeFile(
    path.join(checkpointDir, "H0-B_HEAD断点.json"),
    JSON.stringify({ completed: headResults.length, total: plan.length, results: headResults }, null, 2),
  );

