const h0a06 = workbook("H0-A_06_人工字段隔离检查.xlsx");

const sampleRows = table(sheet(h0a02, "10笔摘要"));
const fillRows = table(sheet(h0a02, "原始Fill链"));
const phaseRows = table(sheet(h0a03, "持仓阶段"));
const demandRows = table(sheet(h0a03, "行情需求去重"));
const auditRows = table(sheet(h0a05, "完整HEAD审计"));
const isolationRows = table(sheet(h0a06, "隔离断言"));

const actualSamples = sampleRows.map((row) => row["新T编号"]);
if (JSON.stringify(actualSamples) !== JSON.stringify(REQUIRED_SAMPLES)) {
  throw new Error(`固定样本不一致: ${actualSamples.join(",")}`);
}
if (sampleRows.some((row) => row["交易来源分类"] !== "个人主动")) {
  throw new Error("固定样本中出现非个人主动记录");
}
if (new Set(sampleRows.map((row) => row.position_cycle_id)).size !== 10) {
  throw new Error("position_cycle_id非空唯一性失败");
}
if (fillRows.length !== 778) throw new Error(`原始Fill行数不是778: ${fillRows.length}`);
if (phaseRows.length !== 42) throw new Error(`持仓阶段数不是42: ${phaseRows.length}`);
if (isolationRows.some((row) => Number(row["实际"]) !== 0 || row["结果"] !== "通过")) {
  throw new Error("H0-A人工字段隔离断言未全部通过");
}
if (demandRows.length !== 30) throw new Error(`去重需求不是30条: ${demandRows.length}`);

const plan = demandRows.map((row, index) => {
  const symbol = String(row.symbol);
  const utcDate = String(row["UTC日期"]);
  const dataType = String(row["数据类型"]);
  const filename = String(row["预计档案文件名"]);
  const url = String(row["完整档案URL"]);
  if (!ALLOWED_TYPES.has(dataType)) throw new Error(`禁止的数据类型: ${dataType}`);
  if (url.includes("/monthly/") || !url.includes("/daily/")) throw new Error(`非日包URL: ${url}`);
  if (url.includes("/trades/")) throw new Error(`禁止下载trades: ${url}`);
  const parsed = new URL(url);
  if (!ALLOWED_HOSTS.has(parsed.hostname) || parsed.protocol !== "https:") {
    throw new Error(`非允许域名或协议: ${url}`);
  }
  if (!url.includes(`/${symbol}/`) || !filename.includes(symbol) || !filename.includes(utcDate)) {
    throw new Error(`symbol/date/文件名不一致: ${url}`);
  }
  const audit = auditMap.get(`${symbol}|${utcDate}|${dataType}`);
  if (!audit) throw new Error(`H0-A_05找不到逐项审计: ${symbol}/${utcDate}/${dataType}`);
  if (
    String(audit["预计档案文件名"]) !== filename ||
    String(audit["完整档案URL"]) !== url ||
    Number(audit["HEAD状态"]) !== 200
  ) {
    throw new Error(`H0-A_03与H0-A_05不一致: ${symbol}/${utcDate}/${dataType}`);
  }
  return {
    plan_id: `H0B-${String(index + 1).padStart(2, "0")}`,
    symbol,
    contract_type: String(row["合约类型"]),
    position_cycle_ids: String(row["position_cycle_id集合"]),
    new_t_ids: String(row["新T编号集合"]),
    beijing_range: String(row["北京时间范围"]),
    utc_range: String(row["UTC时间范围"]),
    utc_date: utcDate,
    data_type: dataType,
    interval: String(row["周期"]),
    filename,
    url,
    checksum_url: `${url}.CHECKSUM`,
    h0a_head_status: Number(row["HEAD状态"]),
    h0a_content_length: Number(row["Content-Length"]),
    h0a_last_modified: String(row["Last-Modified"]),
    related_phase_count: Number(row["关联阶段数"]),
    source_workbook_demand: h0a03.path,
    source_workbook_audit: h0a05.path,
  };

async function headWithRetry(item) {
  const startedAt = new Date().toISOString();
  const started = Date.now();
  let lastError = null;
  for (let attempt = 1; attempt <= 5; attempt += 1) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 15_000);
    try {
      const response = await fetch(item.url, {
        method: "HEAD",
        redirect: "follow",
        signal: controller.signal,
        headers: { "user-agent": "Codex-H0-B-public-market-data-audit/1.0" },
      });
      clearTimeout(timer);
      const record = {
        plan_id: item.plan_id,
        symbol: item.symbol,
        utc_date: item.utc_date,
        data_type: item.data_type,
        method: "HEAD",
        url: item.url,
        started_at: startedAt,
        completed_at: new Date().toISOString(),
        elapsed_ms: Date.now() - started,
        http_status: response.status,
        content_length: Number(response.headers.get("content-length")),
        last_modified: response.headers.get("last-modified"),
        content_type: response.headers.get("content-type"),
        retry_count: attempt - 1,
        attempt_count: attempt,
        final_status: response.status === 200 ? "成功" : response.status === 404 ? "HTTP 404" : "HTTP错误",
        error: null,
        headers: Object.fromEntries(response.headers.entries()),
      };
      if (response.status === 404) return record;
      if (response.status === 429 || response.status >= 500) {
        lastError = `HTTP ${response.status}`;
        await sleep(1_000 * attempt);
        continue;
      }
      return record;
    } catch (error) {
      clearTimeout(timer);
      lastError = String(error?.message ?? error);
      if (attempt < 5) await sleep(1_000 * attempt);
    }
  }
  return {
    plan_id: item.plan_id,
    symbol: item.symbol,
    utc_date: item.utc_date,
    data_type: item.data_type,
    method: "HEAD",
    url: item.url,
    started_at: startedAt,
    completed_at: new Date().toISOString(),
    elapsed_ms: Date.now() - started,
    http_status: 0,
    content_length: null,
    last_modified: null,
    content_type: null,
    retry_count: 4,
    attempt_count: 5,
    final_status: "连接/超时失败",
    error: lastError,
    headers: {},
  };
}

