const planPath = path.join(root, "01_下载计划", "H0-B_下载计划.json");
const plan = JSON.parse(await fsp.readFile(planPath, "utf8"));

for (let index = 0; index < plan.length; index += 1) {
  const item = plan[index];
  const type = item.data_type;
  const zipPath = path.join(root, "02_原始ZIP", type, item.filename);
  const checksumName = `${item.filename}.CHECKSUM`;
  const checksumPath = path.join(root, "03_官方CHECKSUM", type, checksumName);
  const csvName = item.filename.replace(/\.zip$/i, ".csv");
  const csvPath = path.join(root, "04_原始解压CSV", type, csvName);
  const head = headResults.find((row) => row.plan_id === item.plan_id);

