async function sha256(filePath) {
  return await new Promise((resolve, reject) => {
    const hash = crypto.createHash("sha256");
    const stream = fs.createReadStream(filePath);
    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("error", reject);
    stream.on("end", () => resolve(hash.digest("hex")));
  });

async function extractEntry(zipPath, entryName, outputPath) {
  const partPath = `${outputPath}.part`;
  await fsp.rm(partPath, { force: true });
  const output = fs.createWriteStream(partPath, { flags: "wx" });
  const child = spawn("unzip", ["-p", zipPath, entryName], { stdio: ["ignore", "pipe", "pipe"] });
  const errors = [];
  child.stderr.on("data", (chunk) => errors.push(chunk));
  const codePromise = new Promise((resolve, reject) => {
    child.on("error", reject);
    child.on("close", resolve);
  });
  try {
    await pipeline(child.stdout, output);
    const code = await codePromise;
    if (code !== 0) throw new Error(`unzip -p失败: ${Buffer.concat(errors).toString("utf8")}`);
    await fsp.rename(partPath, outputPath);

const headResults = JSON.parse(await fsp.readFile(path.join(root, "日志", "H0-B_HEAD结果.json"), "utf8"));
const records = [];
let blocked = false;
for (let index = 0; index < plan.length; index += 1) {
  const item = plan[index];
  const type = item.data_type;
  const zipPath = path.join(root, "02_原始ZIP", type, item.filename);
  const checksumName = `${item.filename}.CHECKSUM`;
  const checksumPath = path.join(root, "03_官方CHECKSUM", type, checksumName);
  const csvName = item.filename.replace(/\.zip$/i, ".csv");
  const csvPath = path.join(root, "04_原始解压CSV", type, csvName);
  const head = headResults.find((row) => row.plan_id === item.plan_id);

record.official_checksum_content = await fsp.readFile(checksumPath, "utf8");
const checksumMatch = record.official_checksum_content
  .trim()
  .match(/^([0-9a-fA-F]{64})\s+\*?(.+)$/);
if (!checksumMatch) throw new Error("官方CHECKSUM内容格式异常");
record.official_sha256 = checksumMatch[1].toLowerCase();
if (path.basename(checksumMatch[2].trim()) !== item.filename) {
  throw new Error(`官方CHECKSUM文件名不一致: ${checksumMatch[2]}`);

    const zipStat = await fsp.stat(zipPath);
    record.zip_size = zipStat.size;
    record.local_zip_sha256 = await sha256(zipPath);
    record.official_checksum_match = record.local_zip_sha256 === record.official_sha256;
    record.checksum_verified_at = new Date().toISOString();
    if (!record.official_checksum_match) throw new Error("官方CHECKSUM与本地SHA-256不一致");

    const listing = await run("unzip", ["-Z1", zipPath]);
    if (listing.code !== 0) throw new Error(`ZIP目录读取失败: ${listing.stderr}`);
    record.zip_entries = listing.stdout.split("\n").filter(Boolean);
    const test = await run("unzip", ["-t", zipPath]);
    record.zip_structure_ok = test.code === 0 && record.zip_entries.length > 0;
    if (!record.zip_structure_ok) throw new Error(`ZIP结构检查失败: ${test.stderr || test.stdout}`);
    record.internal_filename_ok =
      record.zip_entries.length === 1 && path.basename(record.zip_entries[0]) === csvName;
    if (!record.internal_filename_ok) {
      throw new Error(`ZIP内部文件名异常: ${record.zip_entries.join(",")}`);
    }

    let shouldExtract = true;
    try {
      const existingCsv = await fsp.stat(csvPath);
      if (existingCsv.isFile() && existingCsv.size > 0) shouldExtract = false;
    } catch (error) {
      if (error?.code !== "ENOENT") throw error;
    }
    if (shouldExtract) await extractEntry(zipPath, record.zip_entries[0], csvPath);
    const csvStat = await fsp.stat(csvPath);
    if (csvStat.size <= 0) throw new Error("解压CSV为空");
    record.csv_size = csvStat.size;
    record.csv_sha256 = await sha256(csvPath);
    record.final_status = "通过";
  } catch (error) {
    record.final_status = "阻断";
    record.blocking_reason = String(error?.message ?? error);
    blocked = true;
  }
  records.push(record);
  await Promise.all([
    fsp.writeFile(logPath, JSON.stringify(records, null, 2)),
    fsp.writeFile(
      checkpointPath,
      JSON.stringify(
        {
          updated_at: new Date().toISOString(),
          completed: records.length,
          total: plan.length,
          blocked,
          records,
        },
        null,
        2,
      ),
    ),
  ]);
  console.log(
    `[${String(index + 1).padStart(2, "0")}/${plan.length}] ${item.data_type} ${item.symbol} ${item.utc_date}: ${record.final_status}`,
  );
  if (blocked) break;
}

const status = {
  updated_at: new Date().toISOString(),
  planned_zip_count: plan.length,
  completed_record_count: records.length,
  zip_pass_count: records.filter((row) => row.final_status === "通过").length,
  checksum_download_success_count: records.filter((row) => row.checksum_download?.final_status === "下载成功").length,
  checksum_pass_count: records.filter((row) => row.official_checksum_match).length,
  zip_structure_pass_count: records.filter((row) => row.zip_structure_ok).length,
  internal_filename_pass_count: records.filter((row) => row.internal_filename_ok).length,
  extracted_csv_count: records.filter((row) => row.csv_size > 0).length,
  zip_total_bytes: records.reduce((sum, row) => sum + (row.zip_size ?? 0), 0),
  csv_total_bytes: records.reduce((sum, row) => sum + (row.csv_size ?? 0), 0),
  blocked,
  blocking_items: records
    .filter((row) => row.final_status === "阻断")
    .map((row) => ({ plan_id: row.plan_id, reason: row.blocking_reason })),
};
await fsp.writeFile(statusPath, JSON.stringify(status, null, 2));

