const [inputExtractionArg, rawTradesArg, outputDirArg] = process.argv.slice(2);
if (!inputExtractionArg || !rawTradesArg || !outputDirArg) {
  throw new Error(
    "Usage: node extract_multiplier_evidence.mjs <input_extraction_json> <raw_trades_xlsx> <h0c_output_dir>",
  );
}

const extraction = JSON.parse(await fs.readFile(path.resolve(inputExtractionArg), "utf8"));
const h0a = extraction.workbooks.find(
  (book) => book.filename === "H0-A_02_10笔固定样本客观链核对.xlsx",
);
const fillSheet = h0a.sheets.find((sheet) => sheet.name === "原始Fill链");
const fillHeaderRow = fillSheet.values.findIndex((row) => row[0] === "position_cycle_id");
const fillHeaders = fillSheet.values[fillHeaderRow];
const fillRows = fillSheet.values.slice(fillHeaderRow + 1).filter((row) => row[0]);
const h = Object.fromEntries(fillHeaders.map((name, index) => [name, index]));

const tradeIds = new Set(fillRows.map((row) => String(row[h["Trade/Fill ID"]])));
const fillByTradeId = new Map(
  fillRows.map((row) => [
    String(row[h["Trade/Fill ID"]]),
    {
      position_cycle_id: row[h.position_cycle_id],
      new_t_id: row[h["新T编号"]],
      symbol: row[h["品种"]],
      position_direction: row[h["方向"]],
      event_type: row[h["事件类型"]],
      fill_time_ms: row[h["时间戳毫秒"]],
      trade_id: String(row[h["Trade/Fill ID"]]),
      technical_fill_id: row[h["技术Fill ID"]],
      fill_price_h0a: row[h["成交价格"]],
      fill_quantity_h0a: row[h["成交数量"]],
      position_quantity_before: row[h["事件前持仓数量"]],
      position_avg_price_before: row[h["事件前持仓均价"]],
    },

);

const rawWorkbook = await SpreadsheetFile.importXlsx(await FileBlob.load(path.resolve(rawTradesArg)));
const rawSheet = rawWorkbook.worksheets.getItemAt(0);
const rawValues = rawSheet.getUsedRange(true).values;
const rawHeaderRow = rawValues.findIndex((row) => row.includes("交易 ID") && row.includes("已实现利润"));
if (rawHeaderRow < 0) throw new Error("Raw trade history header not found.");
const rawHeaders = rawValues[rawHeaderRow];
const r = Object.fromEntries(rawHeaders.map((name, index) => [name, index]));
const matched = [];
for (const row of rawValues.slice(rawHeaderRow + 1)) {
  const tradeId = String(row[r["交易 ID"]] ?? "");
  if (!tradeIds.has(tradeId)) continue;
  matched.push({
    ...fillByTradeId.get(tradeId),
    raw_time_bjt: row[r["时间"]],
    raw_symbol: row[r["代币名称/币种名称/币对"]],
    raw_side: row[r["方向"]],
    raw_price: row[r["价格"]],
    raw_quantity: row[r["数量"]],
    raw_amount: row[r["金额"]],
