def candidate_tu(event_time: datetime, cycles: list[dict]) -> str:
    overlapping = []
    for row in cycles:
        if row["_start"] and row["_end"] and row["_start"] <= event_time <= row["_end"]:
            overlapping.extend(row["_ids"])
    if overlapping:
        return "｜".join(sorted(set(overlapping)))
    future = [
