async function exportWorkbook(workbook, fileName) {
  const target = path.join(actualDir, fileName);
  const xlsx = await SpreadsheetFile.exportXlsx(workbook);
  await xlsx.save(target);
  const link = path.join(outputRoot, fileName);
  try {
    const stat = await fs.lstat(link);
    if (stat.isSymbolicLink()) await fs.unlink(link);
    else throw new Error(`Refusing to replace non-symlink output: ${link}`);
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }
  await fs.symlink(path.relative(outputRoot, target), link);
  process.stderr.write(`exported ${fileName}\n`);

