async function downloadToPart(url, finalPath, expectedLength = null) {
  const parsed = new URL(url);
  if (parsed.protocol !== "https:" || !allowedHosts.has(parsed.hostname)) {
    throw new Error(`禁止的下载URL: ${url}`);
  }
  const partPath = `${finalPath}.part`;

await pipeline(Readable.fromWeb(response.body), fs.createWriteStream(partPath, { flags: "wx" }));
clearTimeout(timer);
const fileStat = await fsp.stat(partPath);
const responseLength = Number(response.headers.get("content-length"));
if (Number.isFinite(responseLength) && responseLength > 0 && fileStat.size !== responseLength) {
  throw new Error(`响应Content-Length不一致: ${fileStat.size} != ${responseLength}`);
}
if (Number.isFinite(expectedLength) && expectedLength > 0 && fileStat.size !== expectedLength) {
  throw new Error(`HEAD Content-Length不一致: ${fileStat.size} != ${expectedLength}`);
}
await fsp.rename(partPath, finalPath);

