const workbookCache = new Map();
async function getWorkbook(relativePath) {
  if (!workbookCache.has(relativePath)) {
    const workbook = await SpreadsheetFile.importXlsx(await FileBlob.load(abs(relativePath)));
    workbookCache.set(relativePath, workbook);
  }
  return workbookCache.get(relativePath);
}

async function readRange(relativePath, sheetName, rangeAddress) {
  const workbook = await getWorkbook(relativePath);
  return workbook.worksheets.getItem(sheetName).getRange(rangeAddress).values;
}

